import requests

# Get sequences for other donor candidates
pdb_ids = ['5JZL', '3ADF', '5Y01', '2VZX', '1H6R']  # muGFP, mAzamiGreen, Gamillus, Dendra2, avGFP

for pdb_id in pdb_ids:
    try:
        url = f"https://www.rcsb.org/fasta/entry/{pdb_id}"
        response = requests.get(url, timeout=10)
        if response.status_code == 200:
            print(f"\n{pdb_id}:")
            # Print just the sequence
            lines = response.text.split('\n')
            for line in lines:
                if not line.startswith('>'):
                    print(line)
        else:
            print(f"{pdb_id}: Failed (status {response.status_code})")
    except Exception as e:
        print(f"{pdb_id}: Error - {e}")
